1. //! Error handling.
2. 
3. use core::fmt;
4. 
5. use crate::alloc::String;
6. 
7. /// Errors that may occur during token parsing.
8. #[derive(Debug)]
9. #[non_exhaustive]
10. pub enum ParseError {
11.     /// Token has invalid structure.
12.     ///
13.     /// Valid tokens must consist of 3 base64url-encoded parts (header, claims, and signature)
14.     /// separated by periods.
15.     InvalidTokenStructure,
16.     /// Cannot decode base64.
17.     InvalidBase64Encoding,
18.     /// Token header cannot be parsed.
19.     MalformedHeader(serde_json::Error),
20.     /// [Content type][cty] mentioned in the token header is not supported.
21.     ///
22.     /// Supported content types are JSON (used by default) and CBOR (only if the `serde_cbor`
23.     /// crate feature is enabled, which it is by default).
24.     ///
25.     /// [cty]: https://tools.ietf.org/html/rfc7515#section-4.1.10
26.     UnsupportedContentType(String),
27. }
28. 
29. impl fmt::Display for ParseError {
30.     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
31.         match self {
32.             Self::InvalidTokenStructure => formatter.write_str("invalid token structure"),
33.             Self::InvalidBase64Encoding => write!(formatter, "invalid base64 decoding"),
34.             Self::MalformedHeader(err) => write!(formatter, "malformed token header: {err}"),
35.             Self::UnsupportedContentType(ty) => {
36.                 write!(formatter, "unsupported content type: {ty}")
37.             }
38.         }
39.     }
40. }
41. 
42. #[cfg(feature = "std")]
43. impl std::error::Error for ParseError {
44.     fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
45.         match self {
46.             Self::MalformedHeader(err) => Some(err),
47.             _ => None,
48.         }
49.     }
50. }
51. 
52. /// Errors that can occur during token validation.
53. #[derive(Debug)]
54. #[non_exhaustive]
55. pub enum ValidationError {
56.     /// Algorithm mentioned in the token header differs from invoked one.
57.     AlgorithmMismatch {
58.         /// Expected algorithm name.
59.         expected: String,
60.         /// Actual algorithm in the token.
61.         actual: String,
62.     },
63.     /// Token signature has invalid byte length.
64.     InvalidSignatureLen {
65.         /// Expected signature length.
66.         expected: usize,
67.         /// Actual signature length.
68.         actual: usize,
69.     },
70.     /// Token signature is malformed.
71.     MalformedSignature(anyhow::Error),
72.     /// Token signature has failed verification.
73.     InvalidSignature,
74.     /// Token claims cannot be deserialized from JSON.
