214. mod serde_timestamp {
215.     use chrono::{offset::TimeZone, DateTime, Utc};
216.     use serde::{
217.         de::{Error as DeError, Visitor},
218.         Deserializer, Serializer,
219.     };
220. 
221.     use core::fmt;
222. 
223.     struct TimestampVisitor;
224. 
225.     impl<'de> Visitor<'de> for TimestampVisitor {
226.         type Value = DateTime<Utc>;
227. 
228.         fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
229.             formatter.write_str("UTC timestamp")
230.         }
231. 
232.         fn visit_i64<E>(self, value: i64) -> Result<Self::Value, E>
233.         where
234.             E: DeError,
235.         {
236.             Utc.timestamp_opt(value, 0)
237.                 .single()
238.                 .ok_or_else(|| E::custom("UTC timestamp overflow"))
239.         }
240. 
241.         fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E>
242.         where
243.             E: DeError,
244.         {
245.             let value = i64::try_from(value).map_err(DeError::custom)?;
246.             Utc.timestamp_opt(value, 0)
247.                 .single()
248.                 .ok_or_else(|| E::custom("UTC timestamp overflow"))
249.         }
250.     }
251. 
252.     pub fn serialize<S: Serializer>(
253.         time: &Option<DateTime<Utc>>,
254.         serializer: S,
255.     ) -> Result<S::Ok, S::Error> {
256.         // `unwrap` is safe due to `skip_serializing_if` option
257.         serializer.serialize_i64(time.unwrap().timestamp())
258.     }
259. 
260.     pub fn deserialize<'de, D: Deserializer<'de>>(
261.         deserializer: D,
262.     ) -> Result<Option<DateTime<Utc>>, D::Error> {
263.         deserializer.deserialize_i64(TimestampVisitor).map(Some)
264.     }
265. }
