1. //! RSA-based JWT algorithms: `RS*` and `PS*`.
2. 
3. pub use rsa::{errors::Error as RsaError, RsaPrivateKey, RsaPublicKey};
4. 
5. use rand_core::{CryptoRng, RngCore};
6. use rsa::{BigUint, Pkcs1v15Sign, Pss, PublicKey, PublicKeyParts};
7. use sha2::{Digest, Sha256, Sha384, Sha512};
8. 
9. use core::{fmt, str::FromStr};
10. 
11. use crate::{
12.     alg::{SecretBytes, StrongKey, WeakKeyError},
13.     alloc::{Box, Cow, String, ToOwned, Vec},
14.     jwk::{JsonWebKey, JwkError, KeyType, RsaPrimeFactor, RsaPrivateParts},
15.     Algorithm, AlgorithmSignature,
16. };
17. 
18. /// RSA signature.
19. #[derive(Debug)]
20. #[cfg_attr(docsrs, doc(cfg(feature = "rsa")))]
21. pub struct RsaSignature(Vec<u8>);
22. 
23. impl AlgorithmSignature for RsaSignature {
24.     fn try_from_slice(bytes: &[u8]) -> anyhow::Result<Self> {
25.         Ok(RsaSignature(bytes.to_vec()))
26.     }
27. 
28.     fn as_bytes(&self) -> Cow<'_, [u8]> {
29.         Cow::Borrowed(&self.0)
30.     }
31. }
32. 
33. /// RSA hash algorithm.
34. #[derive(Debug, Copy, Clone, Eq, PartialEq)]
35. enum HashAlg {
36.     Sha256,
37.     Sha384,
38.     Sha512,
39. }
40. 
41. impl HashAlg {
42.     fn digest(self, message: &[u8]) -> Box<[u8]> {
43.         match self {
44.             Self::Sha256 => {
45.                 let digest: [u8; 32] = *(Sha256::digest(message).as_ref());
46.                 Box::new(digest)
