 pub struct WeakKeyError<T>(pub T);

 impl<T> fmt::Display for WeakKeyError<T> {
     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
         formatter.write_str("Weak cryptographic key")
     }
