148. /// # use jwt_compact::alg::{StrongAlg, Rsa};
149. /// const ALG: StrongAlg<Rsa> = StrongAlg(Rsa::rs256());
150. /// // `ALG` will not support RSA keys with unsecure lengths by design!
151. /// ```
