162. impl Algorithm for Rsa {
163.     type SigningKey = RsaPrivateKey;
164.     type VerifyingKey = RsaPublicKey;
165.     type Signature = RsaSignature;
166. 
167.     fn name(&self) -> Cow<'static, str> {
168.         Cow::Borrowed(self.alg_name())
169.     }
170. 
171.     fn sign(&self, signing_key: &Self::SigningKey, message: &[u8]) -> Self::Signature {
172.         let digest = self.hash_alg.digest(message);
173.         let signing_result = match self.padding_scheme() {
174.             PaddingScheme::Pkcs1v15(padding) => {
175.                 signing_key.sign_with_rng(&mut rand_core::OsRng, padding, &digest)
176.             }
177.             PaddingScheme::Pss(padding) => {
178.                 signing_key.sign_with_rng(&mut rand_core::OsRng, padding, &digest)
179.             }
180.         };
181.         RsaSignature(signing_result.expect("Unexpected RSA signature failure"))
182.     }
183. 
184.     fn verify_signature(
185.         &self,
186.         signature: &Self::Signature,
187.         verifying_key: &Self::VerifyingKey,
188.         message: &[u8],
189.     ) -> bool {
190.         let digest = self.hash_alg.digest(message);
191.         let verify_result = match self.padding_scheme() {
192.             PaddingScheme::Pkcs1v15(padding) => {
193.                 verifying_key.verify(padding, &digest, &signature.0)
194.             }
195.             PaddingScheme::Pss(padding) => verifying_key.verify(padding, &digest, &signature.0),
196.         };
197.         verify_result.is_ok()
198.     }
199. }
