379. /// ⚠ **Warning.** Contrary to [RFC 7518], this implementation does not set `dp`, `dq`, and `qi`
380. /// fields in the JWK root object, as well as `d` and `t` fields for additional factors
381. /// (i.e., in the `oth` array).
382. ///
383. /// [RFC 7518]: https://tools.ietf.org/html/rfc7518#section-6.3.2
384. impl<'a> From<&'a RsaPrivateKey> for JsonWebKey<'a> {
385.     fn from(key: &'a RsaPrivateKey) -> JsonWebKey<'a> {
386.         const MSG: &str = "RsaPrivateKey must have at least 2 prime factors";
387. 
388.         let p = key.primes().get(0).expect(MSG);
389.         let q = key.primes().get(1).expect(MSG);
390. 
391.         let private_parts = RsaPrivateParts {
392.             private_exponent: SecretBytes::owned(key.d().to_bytes_be()),
393.             prime_factor_p: SecretBytes::owned(p.to_bytes_be()),
394.             prime_factor_q: SecretBytes::owned(q.to_bytes_be()),
395.             p_crt_exponent: None,
396.             q_crt_exponent: None,
397.             q_crt_coefficient: None,
398.             other_prime_factors: key.primes()[2..]
399.                 .iter()
400.                 .map(|factor| RsaPrimeFactor {
401.                     factor: SecretBytes::owned(factor.to_bytes_be()),
402.                     crt_exponent: None,
403.                     crt_coefficient: None,
404.                 })
405.                 .collect(),
406.         };
407. 
408.         JsonWebKey::Rsa {
409.             modulus: Cow::Owned(key.n().to_bytes_be()),
410.             public_exponent: Cow::Owned(key.e().to_bytes_be()),
411.             private_parts: Some(private_parts),
412.         }
413.     }
414. }
