416. /// ⚠ **Warning.** Contrary to [RFC 7518] (at least, in spirit), this conversion ignores
417. /// `dp`, `dq`, and `qi` fields from JWK, as well as `d` and `t` fields for additional factors.
418. ///
419. /// [RFC 7518]: https://www.rfc-editor.org/rfc/rfc7518.html
420. impl TryFrom<&JsonWebKey<'_>> for RsaPrivateKey {
421.     type Error = JwkError;
422. 
423.     fn try_from(jwk: &JsonWebKey<'_>) -> Result<Self, Self::Error> {
424.         let JsonWebKey::Rsa {
425.             modulus,
426.             public_exponent,
427.             private_parts,
428.         } = jwk else {
429.             return Err(JwkError::key_type(jwk, KeyType::Rsa));
430.         };
431. 
432.         let RsaPrivateParts {
433.             private_exponent: d,
434.             prime_factor_p,
435.             prime_factor_q,
436.             other_prime_factors,
437.             ..
438.         } = private_parts
439.             .as_ref()
440.             .ok_or_else(|| JwkError::NoField("d".into()))?;
441. 
442.         let e = BigUint::from_bytes_be(public_exponent);
443.         let n = BigUint::from_bytes_be(modulus);
444.         let d = BigUint::from_bytes_be(d);
445. 
446.         let mut factors = Vec::with_capacity(2 + other_prime_factors.len());
447.         factors.push(BigUint::from_bytes_be(prime_factor_p));
448.         factors.push(BigUint::from_bytes_be(prime_factor_q));
449.         factors.extend(
450.             other_prime_factors
451.                 .iter()
452.                 .map(|prime| BigUint::from_bytes_be(&prime.factor)),
453.         );
454. 
455.         let key = Self::from_components(n, e, d, factors);
456.         let key = key.map_err(|err| JwkError::custom(anyhow::anyhow!(err)))?;
457.         key.validate()
458.             .map_err(|err| JwkError::custom(anyhow::anyhow!(err)))?;
459.         Ok(key)
460.     }
461. }
