 /// # use rand::thread_rng;
 /// # use jwt_compact::{prelude::*, alg::{Hs256, Hs256Key, StrongAlg, StrongKey}};
 /// # fn main() -> anyhow::Result<()> {
 /// let weak_key = Hs256Key::new(b"too short!");
 /// assert!(StrongKey::try_from(weak_key).is_err());
